      apikey: gnewsApiKey
    })}`;

    const response = await fetch(url, { signal });
    
    if (!response.ok) {
      const error = new Error(`GNews API error: ${response.status}`);
      error.status = response.status;
      throw error;
    }

    const data = await response.json();
    return {
      articles: Array.isArray(data.articles) ? data.articles : [],
      totalResults: data.totalResults || 0
    };
  } catch (error) {
    console.error('Error fetching from GNews:', error);
    throw error;
  }
};

// Enhanced fetch with retry logic
const fetchWithRetry = async (url, options = {}, retries = MAX_RETRIES, delay = 1000) => {
  try {
    // Check rate limits before making a request
    const now = Date.now();
    if (now < rateLimitInfo.reset) {
      const waitTime = rateLimitInfo.reset - now;
      console.warn(`Rate limited. Waiting ${waitTime}ms before next request`);
      await new Promise(resolve => setTimeout(resolve, waitTime));
    }

    // Ensure minimum time between API calls
    const timeSinceLastCall = now - lastApiCallTime;
    if (timeSinceLastCall < MIN_API_INTERVAL) {
      await new Promise(resolve => setTimeout(resolve, MIN_API_INTERVAL - timeSinceLastCall));
    }

    const response = await axios({
      ...options,
      url,
      timeout: 10000, // 10 second timeout
      headers: {
        'User-Agent': 'PulsePoint/1.0',
        ...(options.headers || {})
      }
    });

    // Update rate limit info from headers if available
    if (response.headers) {
      const remaining = response.headers['x-ratelimit-remaining'];
      const reset = response.headers['x-ratelimit-reset'];
      
      if (remaining) {
        rateLimitInfo.remaining = parseInt(remaining, 10);
      }
      if (reset) {
        rateLimitInfo.reset = parseInt(reset, 10) * 1000; // Convert to ms
      }
    }

    lastApiCallTime = Date.now();
    return response;
  } catch (error) {
    if (retries <= 0) {
      console.error('Max retries reached:', error.message);
      throw error;
    }

    // If rate limited, wait and retry
    if (error.response?.status === 429) {
      const retryAfter = error.response.headers['retry-after'] || 5; // Default to 5 seconds
      console.warn(`Rate limited. Retrying after ${retryAfter} seconds...`);
      await new Promise(resolve => setTimeout(resolve, retryAfter * 1000));
      return fetchWithRetry(url, options, retries - 1, delay * 2);
    }

    // For server errors, retry with exponential backoff
    if (error.response?.status >= 500) {
      console.warn(`Server error (${error.response.status}). Retrying...`);
      await new Promise(resolve => setTimeout(resolve, delay));
      return fetchWithRetry(url, options, retries - 1, delay * 2);
    }

    // For other errors, just rethrow
    throw error;
  }
};

